            // Optionally add you Reset facet(s) to the flyout. (These are not in FWP.facets, so will not be in facets_inflyout)
            // IMPORTANT: Remove these 2 lines if not needed!
            let reset_facets_inflyout = ['your_reset_facet_name'];
            facets_inflyout = facets_inflyout.concat(reset_facets_inflyout);

            return facets_inflyout;
          });
        });
      })(fUtil);
    </script>
    <?php
