  <script>
    (function($) {
      document.addEventListener('facetwp-loaded', function() {

        $('.facetwp-facet').each(function() {
          var facet = $(this);
          var facet_name = facet.attr('data-name');
          var facet_type = facet.attr('data-type');
          var facet_label = FWP.settings.labels[facet_name];

            if (facet.closest('.facet-wrap').len() < 1 && facet.closest('.facetwp-flyout').len() < 1) {

              // Wrap the facet in div with class "facet-wrap" for styling and hiding empty facets including the label
              var el = facet.nodes[0];
              var wrapper = document.createElement('div');
              wrapper.className = 'facet-wrap';
              el.parentNode.insertBefore(wrapper, el);
              wrapper.appendChild(el);

              // Don't add a label for these facet types
              if (!['reset', 'pager', 'sort'].includes(facet_type)) {

                // Add the facet label
                facet.nodes[0].insertAdjacentHTML('beforebegin', '<h3 class="facet-label">' + facet_label + '</h3>');

              }
            }
        });
      });
    })(fUtil);
  </script>
  <?php
