  ?>
  <script>

    (function($) {

      function hideEmptyFacets() {

        // This code assumes that each facet is wrapped within a container element with class "facet-wrap".
        // You may need to change the class depending on your setup.
        // For example, change ".facet-wrap" to ".widget" if facets are in WP text widgets.

        $('.facet-wrap').each(function() {

          var el = this;
          var $facet = $(el).find('.facetwp-facet');
          var facet_name = $facet.attr('data-name');
          var facet_type = $facet.attr('data-type');

          if ('pager' == facet_type) {
            // Hide Pager facets if there is only one page, or no results
            if (FWP.settings.pager.total_pages < 2) {
              $(el).addClass('facetwp-hidden');
            } else {
              $(el).removeClass('facetwp-hidden');
            }
          } else {
            // Hide facets if there are 0 choices left
            if ('undefined' !== FWP.settings.num_choices[facet_name] && FWP.settings.num_choices[facet_name] < 1) {
              $(el).addClass('facetwp-hidden');
            } else {
              $(el).removeClass('facetwp-hidden');
            }
          }

        });
      }

      document.addEventListener('facetwp-loaded', function() {
        hideEmptyFacets();
      });

      $().on('click', '.facetwp-flyout-close, .facetwp-flyout-fog', function() {
        hideEmptyFacets();
      });

    })(fUtil);
  </script>
  <?php
}, 100 );

