  <style>
    .facetwp-depth.visible > div:nth-child(n+4 of .facetwp-checkbox),
    .facetwp-depth.visible:not(.showmore) > div:nth-child(n+4 of .facetwp-checkbox) + .facetwp-depth.visible {
      display: none; /* Hide from the 4th choice */
    }
