              FWP.facets[facet_name][minmax] = dateymd;
              inputOrigin._input.value = dateymd;
              if ( ! FWP.auto_refresh === false ) {
                FWP.setHash(); // No refresh when tabbing because then input field focus is lost
              }
            } else {
