  ?>
  <script>

    document.addEventListener('facetwp-maps-loaded', function() {

      const MAX_ZOOM = 20; // Optionally set a limit to the automatically calculated minimum zoom level. Use a value between 1 and 20.

      function getMinZoomToFill(map) {
        const container = map.getDiv();
        const width = container.offsetWidth;
        const height = container.offsetHeight;
        const tileSize = 256;

        const zoomForWidth  = Math.ceil(Math.log2(width  / tileSize));
        const zoomForHeight = Math.ceil(Math.log2(height / tileSize));

        return Math.min(Math.max(zoomForWidth, zoomForHeight), MAX_ZOOM);
      }

      google.maps.event.addListenerOnce(FWP_MAP.map, "idle", () => {
        const minZoom = getMinZoomToFill(FWP_MAP.map);
        FWP_MAP.map.setOptions({ minZoom });
        if (FWP_MAP.map.getZoom() < minZoom) FWP_MAP.map.setZoom(minZoom);
        let initialResize = true;

        // Re-compute on resize
        const resizeObserver = new ResizeObserver(() => {
          if (initialResize) { initialResize = false; return; } // Skip double re-zoom on page load (when resize fires too)
          const minZoom = getMinZoomToFill(FWP_MAP.map);
          FWP_MAP.map.setOptions({ minZoom });
          if (FWP_MAP.map.getZoom() < minZoom) FWP_MAP.map.setZoom(minZoom);
        });
        resizeObserver.observe(FWP_MAP.map.getDiv());
      });

    });
  </script>
  <?php
}, 100 );

