  ?>
  <script>
    document.addEventListener('facetwp-refresh', function() {
      if ('undefined' !== typeof FWP && 'undefined' !== typeof FWP.hooks) {

        FWP.hooks.addFilter('facetwp_map/marker/content', function( content, args, PinElement ) {

          // Create a new marker pin element to overwrite the default one
          const pin = new PinElement({
            scale: 1.5, // Pin scale/size
            background: '#FF0023', // Pin background color
            borderColor: '#FFFFFF', // Pin border color
            glyphColor: '#FFFFFF', // Pin glyph color

            // Set a text or icon as glyph:
            glyphText: '✪', // Glyph Unicode icon. See for example: https://www.amp-what.com/
            // glyphText: 'A', // Glyph text
            // glyphText: '😀', // Use an emoji for the glyph text
            // glyphText: '', // Remove the glyph entirely

            // Use an image as the glyph:
            // - Only works if glyphText is not set!
            // - If you also set glyphColor, the image will get an overlay in that color.
            // glyphSrc: 'https://developers.google.com/maps/documentation/javascript/examples/full/images/beachflag.png'
          });

          // A few ways to add extra styling to the pin, which is an SVG:

          // Style the whole custom marker pin
          pin.style.opacity = '0.5'; // Set CSS opacity
          pin.classList.add('my-pin-class'); // set a custom class on the pin element

          // When using the glyphText option, you can style the SVG > text element (which contains the glyph text) directly.
          // - This element is in a closed shadowRoot, meaning it cannot be reached directly.
          // - Only a few specific inherited CSS styles can be applied.
          // - Setting fontSize will *not* work: Google sets it fixed at 16px.
          // - The only options is to set scale on the pin. When pin scale is set, the font-size will be scaled too.
          pin.style.fontWeight = 'bold'; // set the glyph text font-weight
          pin.style.fontFamily = 'sans-serif'; // set the glyph text font-family
          // pin.style.fontStyle = 'italic'; // set the glyph text font-style
          // pin.style.lineHeight = '1.6'; // set the glyph text line-height

          // Pass the customized pin to the marker content argument
          content = pin;

          return content;

        });
      }
    });
  </script>
  <?php
}, 100 );

