How to use custom PHP code?PHP code can be added to your (child) theme's functions.php file. Alternatively, you can use the Custom Hooks add-on, or a code snippets plugin. More infoadd_action( 'facetwp_scripts', function() {
  ?>
  <script>
    (function($) {
      $(function() {

        if ('object' != typeof FWP) return;

        // Part 1: Create a custom cluster renderer function
        var customrenderer = {

          render: function({count, position}, stats, map) {

            // Set default cluster coloring
            // Change color if this cluster has more markers than the mean cluster, or over 10.
            // Color is purple by default, orange if over 10 or more than mean.
            let color = count > Math.max(10, stats.clusters.markers.mean) ? "#e78b0a" : "#9b0fa5";

            // Optional: set a custom cluster title (visible on hover)
            const title = `Cluster of ${count} markers`;

            // Available cluster data:

            // Cluster location in `position` variable: position.lat() and position.lng():
            // console.log(position.lat());

            // Cluster stats in `stats` variable: total markers, clusters, and min/max/mean number of clusters
            // console.log(stats.clusters);

            // Get the cluster latitude and longitude
            let lat = position.lat();
            let lng = position.lng();

            // ===== Option 1: Cluster color or icon based on cluster  position

            // Set a cluster coloring based on latitude and/or longitude.
            // This example changes the color if the cluster position is roughly within the borders of the European Union.
            if ( ( lat >= 35.0 && lat <= 71.0 ) && ( lng >= -25.0 && lng <= 40.0 ) ) {
              color = "#000000";
            }

            // ===== End Option 1

            // ===== Option 2: Cluster color or icon based on contained post IDs
            // In this example, position.lat() is used to for matching to the post IDs in the cluster, as position is the only cluster data available

            // Cluster color or icon based on contained post IDs
            let postids = [ 6886,5644 ]; // Set an array of post IDs

            // Function to check target latitude agains post latitudes
            function findMatchingCluster(targetLat, targetPostIds) {
              for (let i = 0; i < FWP_MAP.mc.clusters.length; i++) {
                let cluster = FWP_MAP.mc.clusters[i];
                let clusterLat = cluster._position.lat();

                // Check if latitude matches
                if (Math.abs(clusterLat - targetLat) < 0.000001) {

                  // Get markers from this cluster
                  let markers = cluster.markers;
                  let clusterPostIds = markers.map(marker => marker.post_id);

                  // Check if any targetPostId exists in this cluster
                  if (targetPostIds.some(id => clusterPostIds.includes(id))) {
                    return cluster; // Found matching cluster
                  }
                }
              }
              return null;
            }

            // Run the matching function and set the cluster color for matching clusters
            let matchingCluster = findMatchingCluster(lat, postids);
            if ( matchingCluster ) {
              color = "#000000"; // black
            }

            // ===== End Option 2

            // Create a custom HTML marker with an SVG of which the fill color is defined above
            // The default cluster icon SVG is used here
            const pinSvgString = `
              <svg fill="${color}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 240" width="50" height="50">
                <circle cx="120" cy="120" opacity=".6" r="70" />
                <circle cx="120" cy="120" opacity=".3" r="90" />
                <circle cx="120" cy="120" opacity=".2" r="110" />
                <text x="50%" y="50%" style="fill:#fff" text-anchor="middle" font-size="50" dominant-baseline="middle" font-family="roboto,arial,sans-serif">${count}</text>
              </svg>`;

            // Adjust the cluster zIndex to be above other markers
            const zIndex = 1000000 + count;

            // Create the cluster SVG element
            const parser = new DOMParser();
            const pinSvg = parser.parseFromString(pinSvgString, "image/svg+xml").documentElement;

            // Optional: style the cluster icon
            pinSvg.setAttribute("transform", "translate(0 28)");
            pinSvg.querySelector('svg text').style.fontSize = '55px'; // Note that font size is scaled in the SVG sizing
            pinSvg.querySelector('svg text').style.fontWeight = 'bold';

            // Optional: set a cluster icon class
            pinSvg.classList.add('my-cluster-icon'); // set a custom class

            const clusterOptions = {
              map,
              position,
              zIndex,
              title,
              content: pinSvg, // Set the created custom HTML marker
            };

            return new google.maps.marker.AdvancedMarkerElement(clusterOptions);

          }
        }

        // Part 2: Set the above defined custom cluster renderer
        FWP.hooks.addFilter('facetwp_map/clusterer', function(clusterargs, clusterconfig) {

          clusterargs['renderer'] = customrenderer;

          return clusterargs

        });

      });
    })(fUtil);
  </script>
  <?php
}, 100 );

