add_filter( 'facetwp_map_marker_content', function( $content, $post_id, $facet_name, $args ){

  // Get the marker's 'lat' value.
  $latitude = $args['position']['lat'];

  // Get the post's repeater field values.
  $locations = get_field( 'map-repeaterfield', $post_id );

  foreach ( $locations AS $location ) {

    // Check if the 'lat' value of one of the repeater locations matches the  marker's 'lat' value.
    if ( (string)$location['map-repeaterfield-location']['lat'] == (string)$latitude ) {

      // If so, get the value of another field within that repeater field.
      $content = $location['map-repeaterfield-name'];

      // Add more fields data to $content if needed.

      break;
    }
  }

  return $content;
}, 10, 4 );

