How to use custom PHP code?PHP code can be added to your (child) theme's functions.php file. Alternatively, you can use the Custom Hooks add-on, or a code snippets plugin. More info// Part 1 - Prevent an initial map load with all markers.
// This code removes all markers on the initial map load, but only when the Proximity facet has no selection.
// Change "my_proximity_facet" to the name of your Proximity facet.
add_filter( 'facetwp_render_output', function( $output, $params ) {

  foreach ( $params['facets'] as $key => $facet ) {
    if ( 'my_proximity_facet' == $facet['facet_name'] ) {
      if ( empty( $facet['selected_values'] ) ) {
        if ( FWP()->ajax->is_preload && isset( $output['settings']['map']['locations'])  ) {
          $output['settings']['map']['locations'] = [];
        }
      }
    }
  }

  return $output;
}, 11, 2 );

// Part 2 - Trigger a "Locate-me" button click on the first map load, but only when the Proximity facet has no selection.
// This code adds the 'visible' class the first map load or when the first map load has an active Proximity facet.
// Change "my_proximity_facet" to the name of your Proximity facet (2x).
add_action( 'facetwp_scripts', function() {
  ?>
  <script>
    window.addEventListener('DOMContentLoaded', function() {
      if ('undefined' !== typeof FWP.hooks) {

        FWP.hooks.addAction('facetwp/loaded', function() {

          // On first page load, only when the Proximity facet has no selection.
          if ( ! FWP.loaded && ! FWP.facets['my_proximity_facet'].length ) {
            fUtil('.locate-me').trigger('click');
          }
          // After the first map load or when the Proximity facet has a selection on the first map load. 
          if ( FWP.loaded || FWP.facets['my_proximity_facet'].length > 0 ) {
            fUtil('.facetwp-type-map').addClass('visible');
          }
        });
      }

    });
  </script>
  <?php
}, 1000);

// Part 3 - Hide the map on the initial map load, when it loads with no markers.
// Then show it after the "Locate me" button click has triggered, or when the Proximity facet has a selection on the first map load. 
add_action( 'wp_head', function() {
  ?>
  <style>
    .facetwp-type-map {
      display: none;
    }
    .facetwp-type-map.visible {
      display: block;
    }
  </style>
  <?php
}, 100 );

