                  '50%': half,
                  '75%': threequarter,
                  'max': max
                };
                opts.range = surface_area_slider_range_dynamic;

                // End Option 2

                // Set the pips options
                opts.pips = {
                  mode: 'range',
                  density: 3
                }
              }

              return opts;
