  <script>
    (function($) {
      $(function() {
        if ('object' != typeof FWP) return;

        // Customize the facet selection label HTML for all or specific facets. Or remove the label entirely.
        // Default HTML:  <span class="facetwp-selection-label">{selection_label_content}</span>
        // Example: Customize label for the 'my_sort_facet' facet, and remove the label for all other facets.
        FWP.hooks.addFilter('facetwp/selections/facet_selection_label_html', function( selection_label, facet_name ) {
          if ( facet_name == 'my_sort_facet' ) {
