function fwp_disable_indexer( $enabled ) {
  if ( isset( $_REQUEST['action'] ) && $_REQUEST['action'] === 'edit' && isset( $_REQUEST['bulk_edit'] ) ) {
    return false;
  }
  return $enabled;
}

