 * This code works for term fields created in ACF and Pods.
 * 1. Create the facet and set its data source to the taxonomy itself (NOT to the custom term field)
 * 2. Add this code to your (child) theme's functions.php
 * 3. In the code, replace "your_facet_name" with the actual facet name
 * 4. Replace "your_custom_field" with the actual custom field name
 * 5. Re-index after adding this code, and each time when a custom term field value is changed
 */

add_filter( 'facetwp_index_row', function( $params, $class ) {

  if ( 'your_facet_name' == $params['facet_name'] ) {

    // Get the taxonomy term
    $term_id = (int) $params['term_id'];

    // Get the custom field value from the term
    $value = get_term_meta( $term_id, 'your_custom_field', true );

    // Set the facet  label and URL slug to the custom term field value
    $params['facet_display_value'] = $value; // the facet choice label

    // Optional, see explanation below.
    $params['facet_value'] = $value; // the facet URL slug, used for indexing/filtering

  }

  return $params;
}, 10, 2 );

