How to use custom PHP code?PHP code can be added to your (child) theme's functions.php file. Alternatively, you can use the Custom Hooks add-on, or a code snippets plugin. More info// Make FacetWP index recurring events
add_filter( 'facetwp_indexer_row_data', function( $rows, $params ) {

  if ( ! function_exists( 'tribe_events' ) ) {
    return $rows;
  }

  // Add the facet(s) on your events page to the array.
  // Don't include Pager, Sort, Search or Reset facets.
  $events_facets = [ 'my_event_facet' , 'my_other_event_facet' ];

  if ( in_array( $params['facet']['name'], $events_facets ) ) {
    foreach ( $rows as $row ) {
      $post_id = $row['post_id'];

      // Get all occurrence IDs for a "parent" event.
      // This includes the parent event itself, which is also an occurrence.
      $event_ids = tribe_events()->where( 'ID', $post_id )->pluck( 'ID' );

      if ( ! empty( $event_ids ) ) {
        foreach ( $event_ids as $event_id ) {
          $new_row = $row;
          $new_row['post_id'] = $event_id;
          $rows[] = $new_row;
        }
      }
    }
  }

  return $rows;
}, 10, 2 );

