    $start_date = get_post_meta( $occurrence_id, '_EventStartDate', true );
    $start_date_formatted = tribe_get_start_date( $occurrence_id, false, 'F j, Y - H:i' );
    $end_date_formatted = tribe_get_end_date( $occurrence_id, false,'F j, Y - H:i' );
    $title = get_post( $occurrence_id )->post_title;
    $permalink = get_the_permalink( $occurrence_id );

    // Only show occurrence if its start date is after "now":
    if ( $start_date > date( 'Y-m-d H:i:s' ) ) {
      echo '<h2><a href="' . $permalink . '">' . $title . '</a></h2>';
      echo '<p>From: ' . $start_date_formatted . ' to '. $end_date_formatted . '</p>';
    }
  }

endwhile;
else :
  _e( 'Sorry, no posts matched your criteria.' );
endif;
wp_reset_postdata();

