How to use custom PHP code?PHP code can be added to your (child) theme's functions.php file. Alternatively, you can use the Custom Hooks add-on, or a code snippets plugin. More info// Retain the add-to-cart URI and facet selections after a refresh
add_filter( 'woocommerce_product_add_to_cart_url', function( $url, $product ) {

  if ( function_exists('FWP') && strpos( $url, 'add-to-cart' ) > 0 ) {
    $vars = [];
    // First page load
    if ( FWP()->request->is_preload ) {
      array_walk( FWP()->request->url_vars, function( $value, $key ) use (&$vars) {
        $vars[ FWP()->helper->get_setting( 'prefix' ) . $key ] = implode(",",(array)$value);
      }, $vars );
    } else {

      // Retain the URI after a facet refresh
      $custom_path = '/' . FWP()->helper->get_uri() . '/';
      $url = add_query_arg( 'add-to-cart', $product->get_id(), home_url( $custom_path ) );

      $valid_names = wp_list_pluck( FWP()->helper->get_facets(), 'name' );
      $valid_names = array_merge( $valid_names, [ 'paged', 'per_page', 'sort' ] );
      array_walk( FWP()->facet->http_params['get'], function( $value, $key ) use (&$vars, &$valid_names) {
        if ( 0 === strpos( $key, FWP()->helper->get_setting( 'prefix' ) ) && in_array( substr_replace($key, '', 0, strlen(FWP()->helper->get_setting( 'prefix' ))), $valid_names ) ) {
          $vars[ $key ] = implode(",", stripslashes_deep((array)$value));
        }
      } );
    }

    foreach ( $vars AS $facet_name => $value ) {
      $url = add_query_arg( $facet_name, $value, $url  );
    }
  }

  return $url;
}, 20, 2 );

